// Package repository is the tax module's database access layer.
//
// The taxdb package generated by sqlc stays INSIDE this package: only the
// [models] domain types are handed out, and pgtype appears in no signature.
// The boundary is deliberate — the service and API layers do not bind to a
// storage detail, and when the generated code is regenerated only this package
// is affected.
//
// Raw errors do not cross the boundary either: pgx.ErrNoRows and PostgreSQL
// constraint violations are converted here into the typed errors of
// core/errors, so the HTTP layer picks the right status code (plan Section
// 2.7).
//
// # Carrying the transaction
//
// [Repo.WithTx] opens a transaction and puts it into the CONTEXT; while the
// transaction lasts, EVERY repository method called with that context runs in
// the same transaction. The rejected alternative was to put the transaction
// handle into the method signature (this package did so for a while: the
// transaction was opened only INSIDE the repository, with a private helper
// taking `func(q *taxdb.Queries) error`). That form makes it impossible to
// join two repository calls in ONE transaction, because only this package can
// produce the handle and it cannot hand it out — the service cannot keep the
// row it reads its rule from and the row it writes in the same transaction.
// Reducing the signature to types both sides share (context.Context,
// models.*) also lets this package match, STRUCTURALLY, the narrow interface
// the service defines in its OWN package; since ADR 0001 forbids the service
// from importing this package, no type of this package can appear in the
// signature.
//
// A method that takes a lock ([Repo.LockTaxRegion]) returns an error when it is
// called OUTSIDE a transaction: a FOR SHARE lock is released when the
// transaction ends, so a lock without a transaction protects nothing and is
// believed to protect something.
package repository

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/bdrtr/gobit/core/errors"
	"github.com/bdrtr/gobit/internal/modules/tax/repository/taxdb"
)

// Error codes; the calling side can look at these with errors.CodeOf.
const (
	// CodeTaxRegionNotFound reports that the requested tax region was not found.
	CodeTaxRegionNotFound = "tax_region_not_found"
	// CodeTaxRateNotFound reports that the requested tax rate was not found.
	CodeTaxRateNotFound = "tax_rate_not_found"
	// CodeTaxRateRuleNotFound reports that the requested rule was not found.
	CodeTaxRateRuleNotFound = "tax_rate_rule_not_found"
	// CodeTaxClassNotFound reports that the requested tax class was not found.
	CodeTaxClassNotFound = "tax_class_not_found"
	// CodeConstraintViolation reports that a database constraint was violated.
	CodeConstraintViolation = "tax_constraint_violation"
	// CodeDuplicate reports uniqueness violations that have no counterpart IN
	// THE SERVICE (e.g. the same rule written a second time).
	//
	// The two violations the service has its own name for do NOT FALL to this
	// code: a second root region for a country and a second default rate for
	// a region are mapped to the service's code by constraint name (see
	// duplicateCode).
	CodeDuplicate = "tax_duplicate"
	// CodeRegionRootExists reports that the country already has a root tax
	// region; it is the SAME value as service.CodeRootExists.
	CodeRegionRootExists = "tax_region_root_exists"
	// CodeDefaultRateExists reports that the region already has a default
	// rate; it is the SAME value as service.CodeDefaultExists.
	CodeDefaultRateExists = "tax_default_rate_exists"
	// CodeDataInvalid reports that a stored JSON field could not be decoded.
	CodeDataInvalid = "tax_data_invalid"
	// CodeQueryFailed reports an unexpected database error.
	CodeQueryFailed = "tax_query_failed"
	// CodeCanceled reports a context cancellation.
	CodeCanceled = "tax_canceled"
	// CodeTxFailed reports a failure of transaction management.
	CodeTxFailed = "tax_tx_failed"
	// CodeTxRequired reports that a method that takes a lock was called
	// OUTSIDE a transaction; this is a programming error, not client input.
	CodeTxRequired = "tax_tx_required"
)

// rollbackTimeout is the time allowed for a rollback on a canceled context.
//
// The rollback has to be attempted EVEN when the caller's context has ended:
// otherwise the transaction would stay open until the connection returned to
// the pool.
const rollbackTimeout = 5 * time.Second

// txKeyType is the type of the context key; it is unexported so that it cannot
// be produced from outside.
type txKeyType struct{}

// txKey is the key of the transaction handle in the context.
var txKey = txKeyType{}

// PostgreSQL SQLSTATE codes (the ones needed).
const (
	sqlstateCheckViolation       = "23514"
	sqlstateUniqueViolation      = "23505"
	sqlstateForeignKeyViolation  = "23503"
	sqlstateNotNullViolation     = "23502"
	sqlstateStringDataRightTrunc = "22001"
)

// The constraint names that are the database counterparts of the service's
// rules. The names are exactly those of the indexes in the migration; a typo
// here would silently disable the mapping and the codes would diverge again.
const (
	constraintRegionCountryRoot = "tax_region_country_root_uniq"
	constraintRateDefault       = "tax_rate_default_uniq"
)

// Repo provides access to the tax tables. It is safe for concurrent use.
type Repo struct {
	pool *pgxpool.Pool
	q    *taxdb.Queries
}

// New builds a repository that runs on the given pool.
//
// If pool is nil, that is reported as a typed error on the first call, not at
// setup; the setup path does not panic.
func New(pool *pgxpool.Pool) *Repo {
	r := &Repo{pool: pool}
	if pool != nil {
		r.q = taxdb.New(pool)
	}
	return r
}

// ready verifies that the pool can be used.
func (r *Repo) ready() error {
	if r == nil || r.pool == nil || r.q == nil {
		return errors.Unavailable(CodeQueryFailed, "the tax database pool is not set up")
	}
	return nil
}

// WithTx runs fn in a single database transaction.
//
// The context handed to fn CARRIES the transaction: every repository method
// called with that context runs in the same transaction. Every call inside the
// transaction therefore has to be made with the context GIVEN TO FN; if the
// outer ctx is used, that call falls outside the transaction and atomicity is
// silently lost.
//
// If fn returns an error the transaction is ROLLED BACK and the error is passed
// up.
//
// Atomicity is required for two separate classes:
//
//   - The delete paths: when a region is deleted, first the region, then its
//     rates, then their rules are soft-deleted. Had an error struck in
//     between, the region would be deleted but its rates left live; those
//     rates enter no calculation, but they would sit as orphan rows next to a
//     new region opened for the same country and would skew report totals.
//   - The row a service rule reads and the row it writes: a delete that slips
//     between the "is the region live" check and the write cannot be seen
//     while the two are in separate transactions (see [Repo.LockTaxRegion]).
//
// If calls are NESTED, NO new transaction is OPENED; the existing one is used:
// in PostgreSQL a nested transaction means a savepoint, and it would give a
// misleading confidence about the outer transaction's atomicity.
func (r *Repo) WithTx(ctx context.Context, fn func(ctx context.Context) error) error {
	if err := r.ready(); err != nil {
		return err
	}
	if _, ok := txFromContext(ctx); ok {
		return fn(ctx)
	}

	tx, err := r.pool.Begin(ctx)
	if err != nil {
		return wrapDB(err, "the transaction could not be begun")
	}

	committed := false
	defer func() {
		if committed {
			return
		}
		// A short-lived context INDEPENDENT of the caller's is used: if the
		// caller's ctx has been canceled, a rollback made with it would fail
		// instantly too and the transaction would stay open.
		rollbackCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), rollbackTimeout)
		defer cancel()
		_ = tx.Rollback(rollbackCtx)
	}()

	if err := fn(context.WithValue(ctx, txKey, tx)); err != nil {
		return err
	}

	if err := tx.Commit(ctx); err != nil {
		return wrapDB(err, "the transaction could not be committed")
	}
	committed = true
	return nil
}

// txFromContext returns the transaction handle in the context.
func txFromContext(ctx context.Context) (pgx.Tx, bool) {
	tx, ok := ctx.Value(txKey).(pgx.Tx)
	return tx, ok
}

// queries returns the query set that fits the context: the one bound to the
// transaction if there is one, otherwise the one bound to the pool.
func (r *Repo) queries(ctx context.Context) *taxdb.Queries {
	if tx, ok := txFromContext(ctx); ok {
		return r.q.WithTx(tx)
	}
	return r.q
}

// requireTx verifies that the methods that take a lock are called inside a
// transaction.
func requireTx(ctx context.Context, op string) error {
	if _, ok := txFromContext(ctx); !ok {
		return errors.Internal(CodeTxRequired,
			"%s must be called inside a transaction; a FOR SHARE lock without a transaction protects nothing", op)
	}
	return nil
}

// wrapDB turns a raw database error into a typed error.
//
// The classification is deliberate: a constraint violation is a CLIENT error
// (422), a uniqueness violation is a conflict (409), a cancellation is a
// temporary unavailability (503); everything else is a server error and its
// message is NOT LEAKED to the client (see core/http).
//
// The constraint NAME is written into the message: violations of
// "tax_region_country_root_uniq" and "tax_rate_default_uniq" fall into the same
// class, and an administrator can tell which rule they broke only from the
// name. The name also decides the CODE (see duplicateCode).
func wrapDB(err error, format string, a ...any) error {
	if err == nil {
		return nil
	}
	switch {
	case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
		return errors.Wrap(err, errors.KindUnavailable, CodeCanceled, format, a...)
	case errors.Is(err, pgx.ErrTxClosed), errors.Is(err, pgx.ErrTxCommitRollback):
		return errors.Wrap(err, errors.KindInternal, CodeTxFailed, format, a...)
	}

	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		switch pgErr.Code {
		case sqlstateUniqueViolation:
			return errors.Wrap(err, errors.KindConflict, duplicateCode(pgErr.ConstraintName),
				"%s (constraint: %s)", sprintf(format, a...), pgErr.ConstraintName)
		case sqlstateCheckViolation, sqlstateForeignKeyViolation,
			sqlstateNotNullViolation, sqlstateStringDataRightTrunc:
			return errors.Wrap(err, errors.KindInvalid, CodeConstraintViolation,
				"%s (constraint: %s)", sprintf(format, a...), pgErr.ConstraintName)
		}
	}

	return errors.Wrap(err, errors.KindInternal, CodeQueryFailed, format, a...)
}

// duplicateCode maps a uniqueness violation to an error code BY CONSTRAINT
// NAME.
//
// The mapping makes the same situation come back with the same code down both
// paths: the request caught by the service's "read first, then write" check
// gets [CodeRegionRootExists], and the request that passes that check and hits
// the database index (the one that loses the race) has to get the same code.
// Had the two diverged, an admin UI that branches on the code would see the
// same situation under two different codes across two concurrent requests and
// map the message wrongly — and since the error CLASS (conflict) is the same
// down both paths, the difference would escape the tests too.
//
// Constraints whose name is unknown fall to the general [CodeDuplicate]: giving
// an invented name to a violation with no counterpart on the service side would
// branch into a situation that has no caller.
func duplicateCode(constraint string) string {
	switch constraint {
	case constraintRegionCountryRoot:
		return CodeRegionRootExists
	case constraintRateDefault:
		return CodeDefaultRateExists
	default:
		return CodeDuplicate
	}
}

// notFoundOr turns pgx.ErrNoRows into NotFound and everything else into
// wrapDB's result.
func notFoundOr(err error, code, format string, a ...any) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, pgx.ErrNoRows) {
		return errors.NotFound(code, format, a...)
	}
	return wrapDB(err, format, a...)
}

// sprintf formats the error message once.
//
// A call with no arguments returns the format UNCHANGED; otherwise a percent
// sign in the message would reach the user as garbled text (e.g.
// "%!d(MISSING)").
func sprintf(format string, a ...any) string {
	if len(a) == 0 {
		return format
	}
	return fmt.Sprintf(format, a...)
}

// toTime turns a non-NULL timestamp into a UTC time.Time.
//
// An invalid (NULL) timestamp returns the zero time: on NOT NULL columns that
// cannot happen, and if it ever does, the zero time is a value that does not
// panic and that stands out in a test.
func toTime(ts pgtype.Timestamptz) time.Time {
	if !ts.Valid {
		return time.Time{}
	}
	return ts.Time.UTC()
}

// toTimePtr turns a nullable timestamp into a *time.Time.
func toTimePtr(ts pgtype.Timestamptz) *time.Time {
	if !ts.Valid {
		return nil
	}
	t := ts.Time.UTC()
	return &t
}

// fromTime turns a time into a NOT NULL timestamp; it is always written in
// UTC.
func fromTime(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t.UTC(), Valid: true}
}

// toJSONMap turns a jsonb column into a map.
//
// An empty or JSON null value returns a nil map; that way the field does not
// appear in the API response at all (omitempty) instead of showing as
// "metadata": null.
func toJSONMap(raw []byte) (map[string]any, error) {
	if len(raw) == 0 || string(raw) == "null" {
		return nil, nil
	}
	var out map[string]any
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, errors.Wrap(err, errors.KindInternal, CodeDataInvalid,
			"the JSON field could not be decoded")
	}
	if len(out) == 0 {
		return nil, nil
	}
	return out, nil
}

// fromJSONMap turns a map into the bytes to write into a jsonb column.
//
// An empty map writes "{}": the column is NOT NULL, and the distinction between
// "no metadata" and "empty metadata" means nothing in this module.
func fromJSONMap(m map[string]any) ([]byte, error) {
	if len(m) == 0 {
		return []byte("{}"), nil
	}
	raw, err := json.Marshal(m)
	if err != nil {
		return nil, errors.Wrap(err, errors.KindInvalid, CodeDataInvalid,
			"the JSON field could not be encoded")
	}
	return raw, nil
}

// optionalText turns an empty string into SQL NULL and a non-empty one into a
// pointer.
func optionalText(value string) *string {
	if value == "" {
		return nil
	}
	out := value
	return &out
}
